## CVXPY SOURCE: expressions/expression.py
## Expression -- base class for mathematical expressions
##
## CVXPY 1.9 parity notes:
##  - DNLP predicates mirror expression.py:349-405: `is_smooth`,
##    `is_dnlp`, and the linearizable-convex / linearizable-concave hooks.
##  - CVXPY makes the linearizable hooks abstract on Expression; CVXR uses
##    FALSE defaults, matching the existing `is_convex` / `is_concave` default
##    style and relying on Leaf, Atom, and transforms for concrete behavior.


Expression <- new_class("Expression", parent = Canonical, package = "CVXR",
  properties = list(
    shape = new_property(class = class_integer, default = c(1L, 1L))
  )
)

## Register with S4 so that method([, Expression) and similar primitives work.
## Required before using S7::method() for S4 generics like `[`.
S4_register(Expression)

# -- Curvature methods (cached) ----------------------------------------
## CVXPY SOURCE: expression.py line 337-341

## is_constant(): 0 in shape OR all args constant
## Every cached member goes through compute_once (utilities/performance_utils.R),
## the one mirror of CVXPY's @perf.compute_once: keyed on the DPP scopes.
method(is_constant, Expression) <- function(x) {
  compute_once(x, "is_constant", .expression_is_constant)
}
.expression_is_constant <- function(x) {
  (0L %in% .shape(x)) || .all_args(x, is_constant)
}

## is_affine(): constant OR (convex AND concave)
## CVXPY SOURCE: expression.py line 344-347
method(is_affine, Expression) <- function(x) {
  compute_once(x, "is_affine", .expression_is_affine)
}
.expression_is_affine <- function(x) {
  is_constant(x) || (is_convex(x) && is_concave(x))
}

## is_convex() / is_concave() -- abstract on Expression, concrete on Leaf/Atom
## Default implementation: FALSE (subclasses override)
method(is_convex, Expression) <- function(x) FALSE
method(is_concave, Expression) <- function(x) FALSE

## is_dcp(): convex OR concave
## CVXPY SOURCE: expression.py line 382-399
method(is_dcp, Expression) <- function(x) compute_once(x, "is_dcp", .expression_is_dcp)
.expression_is_dcp <- function(x) is_convex(x) || is_concave(x)

## is_dpp(): one DCP (or DGP) pass inside the DPP scope, where a Parameter is
## affine rather than constant and the per-atom DPP restrictions live in the
## curvature hooks (is_atom_convex / is_atom_concave reading dpp_scope_active():
## kron.R, conv.R, quad_form.R, quad_over_lin.R, perspective.R, dotsort.R,
## binary_operators.R). Variable bounds are checked once, by the Problem
## (problem.py:400). Until 1.9.2.9163 this method also recursed over the
## arguments to reach per-class is_dpp methods; that loop was CVXR's own, cost
## about 30% of a compile-time DPP pass on a 405-node expression, and made
## `indicator(...) + x` and an expression over a Variable with a non-affine
## bound non-DPP where upstream says DPP (claims audit decision 29, C0428).
## CVXPY SOURCE: atom.py lines 300-308
## atom.py:307-308 `raise ValueError('Unsupported context ', context)`
## (ported 1.9.2.9162, decision 26).
method(is_dpp, Expression) <- function(x, context = "dcp") {
  ctx <- tolower(context)
  if (!ctx %in% c("dcp", "dgp")) {
    cli_abort("Unsupported context {.val {context}}; use {.val dcp} or {.val dgp}.")
  }
  if (identical(ctx, "dgp")) with_dpp_scope(is_dgp(x))
  else with_dpp_scope(is_dcp(x))
}

