## is_log_log_constant: elementwise strictly positive constant
## CVXPY SOURCE: expression.py lines 407-416
## NOT a generic -- same logic for all Expression types.
is_log_log_constant <- function(x) {
  if (!is_constant(x)) return(FALSE)
  ## Constant and Parameter: use is_pos() (attribute-based)
  if (.s7_is(x, Constant) || .s7_is(x, Parameter)) {
    return(is_pos(x))
  }
  ## Other constant expressions: check actual value > 0
  v <- value(x)
  !is.null(v) && all(v > 0)
}

## is_log_log_*: default FALSE (overridden by atoms)
## CVXPY SOURCE: expression.py lines 418-435
method(is_log_log_convex, Expression) <- function(x) FALSE
method(is_log_log_concave, Expression) <- function(x) FALSE
method(is_log_log_affine, Expression) <- function(x) {
  is_log_log_constant(x) || (is_log_log_convex(x) && is_log_log_concave(x))
}

## is_dgp: checks whether the expression is log-log DCP
## CVXPY SOURCE: expression.py lines 437-448
method(is_dgp, Expression) <- function(x) {
  is_log_log_convex(x) || is_log_log_concave(x)
}

# -- curvatures / log_log_curvature ------------------------------------
## CVXPY SOURCE: expression.py lines 272-290 (curvatures) and 321-334
## (log_log_curvature); properties in CVXPY, functions here.

#' All Curvatures of an Expression
#'
#' Lists every curvature that holds for an expression, DCP, DGP and DQCP
#' alike, as CVXPY's \code{Expression.curvatures}. \code{\link{curvature}}
#' reports only the strongest DCP curvature.
#'
#' @param x A CVXR expression.
#' @returns A character vector, in the order \code{"CONSTANT"},
#'   \code{"AFFINE"}, \code{"CONVEX"}, \code{"CONCAVE"},
#'   \code{"LOG-LOG CONSTANT"}, \code{"LOG-LOG AFFINE"},
#'   \code{"LOG-LOG CONVEX"}, \code{"LOG-LOG CONCAVE"}, \code{"QUASILINEAR"},
#'   \code{"QUASICONVEX"}, \code{"QUASICONCAVE"}, holding those that apply;
#'   \code{"UNKNOWN"} alone if none does.
#' @seealso [curvature()], [log_log_curvature()]
#' @export
curvatures <- function(x) {
  checks <- list(
    list(is_constant, CONSTANT_CURV),
    list(is_affine, AFFINE),
    list(is_convex, CONVEX),
    list(is_concave, CONCAVE),
    list(is_log_log_constant, LOG_LOG_CONSTANT),
    list(is_log_log_affine, LOG_LOG_AFFINE),
    list(is_log_log_convex, LOG_LOG_CONVEX),
    list(is_log_log_concave, LOG_LOG_CONCAVE),
    list(is_quasilinear, QUASILINEAR),
    list(is_quasiconvex, QUASICONVEX),
    list(is_quasiconcave, QUASICONCAVE))
  out <- character(0)
  for (ck in checks) if (ck[[1L]](x)) out <- c(out, ck[[2L]])
  if (length(out) == 0L) UNKNOWN_CURVATURE else out
}

#' Log-Log Curvature of an Expression
#'
#' The DGP analogue of \code{\link{curvature}}, as CVXPY's
#' \code{Expression.log_log_curvature}.
#'
#' @param x A CVXR expression.
#' @returns Character: the first of \code{"LOG-LOG CONSTANT"},
#'   \code{"LOG-LOG AFFINE"}, \code{"LOG-LOG CONVEX"},
#'   \code{"LOG-LOG CONCAVE"} that holds, else \code{"UNKNOWN"}.
#' @seealso [curvatures()], [is_dgp()]
#' @export
log_log_curvature <- function(x) {
  if (is_log_log_constant(x)) LOG_LOG_CONSTANT
  else if (is_log_log_affine(x)) LOG_LOG_AFFINE
  else if (is_log_log_convex(x)) LOG_LOG_CONVEX
  else if (is_log_log_concave(x)) LOG_LOG_CONCAVE
  else UNKNOWN_CURVATURE
}

