# -- label / set_label / format_labeled --------------------------------
## CVXPY SOURCE: expression.py lines 203-263
##
## Storage: each Expression already carries a `.cache` env (mutable
## reference semantics).  CVXPY uses `self._label = None`; we use
## `x@.cache$.label` and treat absent / NULL as "no label set".

method(label, Expression) <- function(x) {
  if (exists(".label", envir = x@.cache, inherits = FALSE)) {
    get(".label", envir = x@.cache, inherits = FALSE)
  } else NULL
}

## CVXPY SOURCE: expression.py lines 208-224 (label setter + deleter)
method(`label<-`, Expression) <- function(x, value) {
  if (is.null(value)) {
    if (exists(".label", envir = x@.cache, inherits = FALSE)) {
      rm(list = ".label", envir = x@.cache)
    }
  } else {
    assign(".label", as.character(value)[[1L]], envir = x@.cache)
  }
  invisible(x)
}

## CVXPY SOURCE: expression.py lines 226-247 (set_label, returns self).
method(set_label, Expression) <- function(x, value) {
  label(x) <- value
  invisible(x)
}

## CVXPY SOURCE: expression.py lines 249-263 (format_labeled base).
## If a label is set, return it; otherwise default to expr_name().
## Atom subclasses with a custom expr_name override format_labeled to
## recurse via format_labeled() on children (see atom.R and per-atom files).
method(format_labeled, Expression) <- function(x) {
  lbl <- label(x)
  if (!is.null(lbl)) return(lbl)
  expr_name(x)
}

# -- print method -----------------------------------------------------

method(print, Expression) <- function(x, ...) {
  cat(sprintf("%s\n", expr_name(x)))
  invisible(x)
}

## CVXPY v1.9.0 fix: #3180 _pow_const_base (expression.py:57-73) + __rpow__
## (expression.py:688-705). Helper for b^x where b is a positive constant and
## x is a CVXPY Expression. Validates that base is constant and positive, then
## returns exp(x * log(b)) via the identity b^x = exp(x * log(b)).
## In CVXR, `^` (Ops group, both directions) and the `power()` factory route
## the const-base / variable-exponent case here.
.pow_const_base <- function(base, exponent) {
  base <- as_expr(base)
  if (!is_constant(base)) {
    cli_abort("The base of {.code b^x} must be a constant when the exponent is a variable.")
  }
  if (!is_pos(base)) {
    cli_abort("The base of {.code b^x} must be positive since we use {.code b^x = exp(x * log(b))}.")
  }
  Exp(Multiply(exponent, Log(base)))
}
